import { randomUUID } from "node:crypto";
import { DomainError } from "../domain/errors";
import { FulfilmentState, Order, OrderLine, OrderState } from "../domain/order";
import { OrderRepository, ProductRepository } from "../domain/repositories";
import { Product } from "../domain/product";

export interface CreateProductInput {
  id: string;
  name: string;
  stock: number;
}

export interface PlaceOrderInput {
  items: readonly OrderLine[];
}

export class OrderService {
  public constructor(
    private readonly products: ProductRepository,
    private readonly orders: OrderRepository,
    private readonly createId: () => string = randomUUID,
  ) {}

  public addProduct(input: CreateProductInput): Product {
    if (this.products.findById(input.id)) {
      throw new DomainError("DUPLICATE_PRODUCT", `Product ${input.id} already exists.`);
    }
    const product = new Product(input.id, input.name, input.stock);
    this.products.save(product);
    return product;
  }

  public placeOrder(input: PlaceOrderInput): Order {
    const items = this.normaliseItems(input.items);
    const products = items.map((item) => {
      const product = this.products.findById(item.productId);
      if (!product) {
        throw new DomainError("PRODUCT_NOT_FOUND", `Product ${item.productId} does not exist.`);
      }
      if (item.quantity > product.availableStock) {
        throw new DomainError("INSUFFICIENT_STOCK", `Insufficient stock for product ${item.productId}.`);
      }
      return product;
    });

    // Availability is checked for every line before making any reservation.
    items.forEach((item, index) => products[index].reserve(item.quantity));
    const order = new Order(this.createId(), items);
    this.orders.save(order);
    return order;
  }

  public progressOrder(orderId: string, nextState: FulfilmentState): Order {
    const order = this.requireOrder(orderId);
    order.advanceTo(nextState);
    this.orders.save(order);
    return order;
  }

  public cancelOrder(orderId: string): Order {
    const order = this.requireOrder(orderId);
    order.cancel();
    order.items.forEach((item) => this.requireProduct(item.productId).release(item.quantity));
    this.orders.save(order);
    return order;
  }

  public listOrders(state?: OrderState): Order[] {
    return this.orders.list(state);
  }

  public listProducts(): Product[] {
    return this.products.list();
  }

  private requireOrder(id: string): Order {
    const order = this.orders.findById(id);
    if (!order) throw new DomainError("ORDER_NOT_FOUND", `Order ${id} does not exist.`);
    return order;
  }

  private requireProduct(id: string): Product {
    const product = this.products.findById(id);
    if (!product) throw new DomainError("PRODUCT_NOT_FOUND", `Product ${id} does not exist.`);
    return product;
  }

  private normaliseItems(items: readonly OrderLine[]): OrderLine[] {
    if (!Array.isArray(items) || items.length === 0) {
      throw new DomainError("INVALID_ORDER", "An order requires at least one item.");
    }
    const quantities = new Map<string, number>();
    for (const item of items) {
      if (!item || typeof item.productId !== "string" || !item.productId.trim() ||
          !Number.isSafeInteger(item.quantity) || item.quantity <= 0) {
        throw new DomainError("INVALID_ORDER", "Each order item needs a product id and positive integer quantity.");
      }
      quantities.set(item.productId, (quantities.get(item.productId) ?? 0) + item.quantity);
    }
    return [...quantities].map(([productId, quantity]) => ({ productId, quantity }));
  }
}

